  /* ---------- mp ---------- */
  "mp.eyebrow": { en: "Mentorship programme", bm: "Program mentorship" },
  "mp.h1": { en: "Alongside women who <span class=\"serif-i\">have already done it</span>", bm: "Bersama wanita yang <span class=\"serif-i\">sudah melaluinya</span>" },
  "mp.lede": { en: "Strivers' Hub connects women entrepreneurs with industry professionals for shared knowledge, collaboration and support that lasts.", bm: "Strivers' Hub menghubungkan usahawanita dengan profesional industri untuk perkongsian ilmu, kerjasama, dan sokongan yang berterusan." },
  "mp.cta": { en: "Register your interest", bm: "Daftar minat anda" },
  "mp.benEyebrow": { en: "What you get", bm: "Apa yang anda dapat" },
  "mp.benH": { en: "Three things that <span class=\"serif-i\">actually change</span>", bm: "Tiga perkara yang <span class=\"serif-i\">benar-benar berubah</span>" },
  "mp.b1t": { en: "Shared knowledge and expertise", bm: "Perkongsian ilmu dan kepakaran" },
  "mp.b1b": { en: "Practical advice from women in the same industry — drawn from real wins and real failures, not theory.", bm: "Nasihat praktikal daripada wanita dalam industri yang sama — berdasarkan kejayaan dan kegagalan sebenar, bukan teori." },
  "mp.b2t": { en: "Room to collaborate", bm: "Peluang kerjasama" },
  "mp.b2b": { en: "Strong ties inside the community surface complementary skills and resources, and often turn into partnerships.", bm: "Hubungan yang kukuh dalam komuniti mendedahkan kemahiran dan sumber yang saling melengkapi, dan selalunya membawa kepada perkongsian perniagaan." },
  "mp.b3t": { en: "Motivation and resilience", bm: "Motivasi dan daya tahan" },
  "mp.b3b": { en: "Celebrating wins and working through setbacks together builds a confidence that is hard to build alone.", bm: "Meraikan kejayaan dan mengharungi cabaran bersama membina keyakinan yang sukar dibina seorang diri." },
  "mp.formEyebrow": { en: "Waiting list", bm: "Senarai menunggu" },
  "mp.formH": { en: "Register your interest", bm: "Daftar minat anda" },
  "mp.formP": { en: "Be the first to know when the next mentorship cohort opens. We will contact you directly with the details.", bm: "Jadilah yang pertama tahu apabila kohort mentorship seterusnya dibuka. Kami hubungi anda terus dengan butiran penyertaan." },
  "mp.f1": { en: "First name", bm: "Nama pertama" },
  "mp.f2": { en: "Last name", bm: "Nama akhir" },
  "mp.f3": { en: "Email address", bm: "Alamat e-mel" },
  "mp.f4": { en: "Phone number", bm: "Nombor telefon" },
  "mp.send": { en: "Submit interest", bm: "Hantar minat" },
  "mp.note": { en: "We use these details only to contact you about the mentorship programme.", bm: "Kami gunakan butiran ini hanya untuk menghubungi anda tentang program mentorship." },
  "mp.doneH": { en: "Thank you — you are on the list", bm: "Terima kasih — anda dalam senarai" },
  "mp.doneP": { en: "We will email you as soon as the next cohort opens. In the meantime, the self-assessment helps us match you to the right mentor.", bm: "Kami akan e-mel anda sebaik sahaja kohort seterusnya dibuka. Sementara itu, penilaian kendiri akan membantu kami memadankan anda dengan mentor yang sesuai." },
  "mp.doneB": { en: "Take the assessment", bm: "Ambil penilaian" },

