  "path.1b": { en: "You have the idea, the drive and maybe a first customer. What is missing is structure.", bm: "Anda ada idea, semangat dan mungkin pelanggan pertama. Yang belum ada: struktur." },
  "path.1l": { en: "Business registration & licensing|Building an online presence|Financial planning basics", bm: "Pendaftaran & pelesenan perniagaan|Membina kehadiran dalam talian|Asas perancangan kewangan" },
