  "path.2b": { en: "The business is running. The challenge now is managing it, not starting it.", bm: "Perniagaan sudah berjalan. Cabarannya kini adalah mengurus, bukan memulakan." },
  "path.2l": { en: "Day-to-day operations|Cost control & budgeting|Human resource management", bm: "Pengurusan operasi harian|Kawalan kos & belanjawan|Pengurusan sumber manusia" },
  "path.2f": { en: "4 recommended resources", bm: "4 sumber disyorkan" },
  "path.3t": { en: "Growing", bm: "Growing" },
  "path.3b": { en: "You are stable and ready to expand. Now it is about scale and networks.", bm: "Anda sudah stabil dan bersedia meluas. Sekarang ia tentang skala dan rangkaian." },
  "path.3l": { en: "Business expansion strategy|Advanced digital marketing|Networks & strategic partnerships", bm: "Strategi pengembangan perniagaan|Pemasaran digital lanjutan|Rangkaian & perkongsian strategik" },
